// Tiger, Tiger2, Streebog, CRC-32, CRC-32C, XXH32 and XXH64 (crypto-api 0.8.5 has none of them, so
// there is no original to compare with).
//
// References that share nothing with the code under test:
//   - the published test vectors (Tiger and Tiger2 design vectors, RFC 6986, the CRC-32C vectors of
//     RFC 3720, the xxHash reference values),
//   - test/vectors/blocks/*.json, generated by scripts/gen-block-vectors.py from a Python
//     implementation of Tiger and Streebog written from the specifications,
//   - `zlib.crc32` of Node for CRC-32,
//   - `std.hash.XxHash32/64` and `std.hash.crc` in the Zig tests of the cores.
// Every test that exercises a hasher runs twice: with the wasm engine, and with the plain-JavaScript
// engine that environments without WebAssembly use. A test also checks that the two agree on random
// inputs and options.
import { describe, it, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { crc32 as zlibCrc32 } from 'node:zlib';
import { readFileSync } from 'node:fs';

import Tiger, { _internal as tigerInternal } from '../packages/crypto-api/src/hasher/tiger.mjs';
import Tiger2, { _internal as tiger2Internal } from '../packages/crypto-api/src/hasher/tiger2.mjs';
import Streebog, { _internal as streebogInternal } from '../packages/crypto-api/src/hasher/streebog.mjs';
import Crc32, { _internal as crc32Internal } from '../packages/crypto-api/src/hasher/crc32.mjs';
import Crc32c, { _internal as crc32cInternal } from '../packages/crypto-api/src/hasher/crc32c.mjs';
import XxHash32, { _internal as xxhash32Internal } from '../packages/crypto-api/src/hasher/xxhash32.mjs';
import XxHash64, { _internal as xxhash64Internal } from '../packages/crypto-api/src/hasher/xxhash64.mjs';
import { sbox as tigerSbox } from '../packages/crypto-api/src/blocks/tiger.mjs';
import Hasher from '../packages/crypto-api/src/hasher/hasher.mjs';
import Hmac from '../packages/crypto-api/src/mac/hmac.mjs';
import CryptoApi from '../packages/crypto-api/src/crypto-api.mjs';
import { toHex } from '../packages/crypto-api/src/encoder/hex.mjs';
import { fromUtf } from '../packages/crypto-api/src/encoder/utf.mjs';

const vectors = (name) => JSON.parse(readFileSync(new URL(`./vectors/blocks/${name}`, import.meta.url), 'utf8'));

/** The same test inputs as scripts/gen-block-vectors.py. */
const pattern = (length, tag) => Buffer.from(Array.from({ length }, (_, i) => (i * 31 + tag * 17 + length) & 255));

/** Deterministic pseudo-random bytes. */
function bytes(length, seed) {
  const out = Buffer.alloc(length);
  let x = (Math.imul(seed, 2654435761) + 12345) >>> 0;
  for (let i = 0; i < length; i++) {
    x = (Math.imul(x, 1664525) + 1013904223) >>> 0;
    out[i] = x >>> 24;
  }
  return out;
}

const ALGOS = {
  tiger: { C: Tiger, internal: tigerInternal, options: {}, block: 64, digest: 24, file: 'tiger.json' },
  tiger2: { C: Tiger2, internal: tiger2Internal, options: {}, block: 64, digest: 24, file: 'tiger2.json' },
  streebog256: { C: Streebog, internal: streebogInternal, options: { length: 256 }, block: 64, digest: 32, file: 'streebog256.json' },
  streebog512: { C: Streebog, internal: streebogInternal, options: { length: 512 }, block: 64, digest: 64, file: 'streebog512.json' },
  crc32: { C: Crc32, internal: crc32Internal, options: {}, block: 64, digest: 4 },
  crc32c: { C: Crc32c, internal: crc32cInternal, options: {}, block: 64, digest: 4 },
  xxhash32: { C: XxHash32, internal: xxhash32Internal, options: {}, block: 16, digest: 4 },
  xxhash64: { C: XxHash64, internal: xxhash64Internal, options: {}, block: 32, digest: 8 },
};
const INTERNALS = [tigerInternal, tiger2Internal, streebogInternal, crc32Internal, crc32cInternal, xxhash32Internal, xxhash64Internal];
const ENGINES = [['wasm', false], ['js', true]];

/** Run `body(engineLabel)` once per engine. */
function perEngine(name, body) {
  for (const [label, disable] of ENGINES) {
    describe(`${name} (${label} engine)`, () => {
      before(() => INTERNALS.forEach((i) => i.reset(disable)));
      after(() => INTERNALS.forEach((i) => i.reset(false)));
      body(label);
    });
  }
}

/** Run `fn` with the plain-JS engines, then restore wasm. */
function withJs(fn) {
  INTERNALS.forEach((i) => i.reset(true));
  try {
    return fn();
  } finally {
    INTERNALS.forEach((i) => i.reset(false));
  }
}

/** Feed `message` to `hasher` in pieces of pseudo-random size 1..maxPiece. */
function feed(hasher, message, seed, maxPiece = 200) {
  let pos = 0;
  let x = seed;
  while (pos < message.length) {
    x = (Math.imul(x, 1664525) + 1013904223) >>> 0;
    const n = 1 + ((x >>> 8) % maxPiece);
    hasher.update(message.subarray(pos, pos + n));
    pos += n;
  }
}

const hexOf = (C, options, message) => {
  const h = new C(options);
  h.update(message);
  return toHex(h.finalize());
};

// ---- published answers ------------------------------------------------------------------------

const M1 = '012345678901234567890123456789012345678901234567890123456789012';
const NOBODY = 'Nobody inspects the spammish repetition';
const published = [
  // Tiger and Tiger2: the test vectors of the design.
  ['tiger', '', '3293ac630c13f0245f92bbb1766e16167a4e58492dde73f3'],
  ['tiger', 'abc', '2aab1484e8c158f2bfb8c5ff41b57a525129131c957b5f93'],
  ['tiger', 'Tiger', 'dd00230799f5009fec6debc838bb6a27df2b9d6f110c7937'],
  ['tiger', 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+-', 'f71c8583902afb879edfe610f82c0d4786a3a534504486b5'],
  ['tiger', 'ABCDEFGHIJKLMNOPQRSTUVWXYZ=abcdefghijklmnopqrstuvwxyz+0123456789', '48ceeb6308b87d46e95d656112cdf18d97915f9765658957'],
  ['tiger', 'Tiger - A Fast New Hash Function, by Ross Anderson and Eli Biham', '8a866829040a410c729ad23f5ada711603b3cdd357e4c15e'],
  ['tiger', 'a'.repeat(1000000), '6db0e2729cbead93d715c6a7d36302e9b3cee0d2bc314b41'],
  ['tiger2', '', '4441be75f6018773c206c22745374b924aa8313fef919f41'],
  ['tiger2', 'abc', 'f68d7bc5af4b43a06e048d7829560d4a9415658bb0b1f3bf'],
  // Streebog: the empty message and the 63-byte message of RFC 6986, in the order the common tools print.
  ['streebog256', '', '3f539a213e97c802cc229d474c6aa32a825a360b2a933a949fd925208d9ce1bb'],
  ['streebog256', M1, '9d151eefd8590b89daa6ba6cb74af9275dd051026bb149a452fd84e5e57b5500'],
  ['streebog512', '', '8e945da209aa869f0455928529bcae4679e9873ab707b55315f56ceb98bef0a7362f715528356ee83cda5f2aac4c6ad2ba3a715c1bcd81cb8e9f90bf4c1c1a8a'],
  ['streebog512', M1, '1b54d01a4af5b9d5cc3d86d68d285462b19abc2475222f35c085122be4ba1ffa00ad30f8767b3a82384c6574f024c311e2a481332b08ef7f41797891c1646f48'],
  // CRC-32 and CRC-32C: the check values.
  ['crc32', '', '00000000'],
  ['crc32', '123456789', 'cbf43926'],
  ['crc32c', '', '00000000'],
  ['crc32c', '123456789', 'e3069283'],
  // xxHash: the reference values (seed 0).
  ['xxhash32', '', '02cc5d05'],
  ['xxhash32', 'abc', '32d153ff'],
  ['xxhash32', NOBODY, 'e2293b2f'],
  ['xxhash64', '', 'ef46db3751d8e999'],
  ['xxhash64', 'abc', '44bc2cf5ad770999'],
  ['xxhash64', NOBODY, 'fbcea83c8a378bf1'],
];

// CRC-32C vectors of RFC 3720 appendix B.4 (32 bytes), seeded xxHash values.
const bytesOf = (f) => Buffer.from(Array.from({ length: 32 }, (_, i) => f(i)));
const published2 = [
  ['crc32c', bytesOf(() => 0), '8a9136aa', {}],
  ['crc32c', bytesOf(() => 0xff), '62a8ab43', {}],
  ['crc32c', bytesOf((i) => i), '46dd794e', {}],
  ['crc32c', bytesOf((i) => 31 - i), '113fdb5c', {}],
  ['xxhash32', '', '36b78ae7', { seed: 0x9E3779B1 }],
  ['xxhash64', '', 'ac75fda2929b17ef', { seed: 0x9E3779B1 }],
];

perEngine('known answers', () => {
  for (const [name, message, want] of published) {
    const a = ALGOS[name];
    it(`${name} of ${JSON.stringify(message.length > 40 ? message.slice(0, 20) + '... (' + message.length + ' bytes)' : message)}`, () => {
      assert.equal(hexOf(a.C, a.options, message), want);
      // Fed byte by byte (up to a short message) and in odd pieces, the digest is the same.
      if (message.length <= 100) {
        const h = new a.C(a.options);
        for (const ch of message) h.update(ch);
        assert.equal(toHex(h.finalize()), want);
      }
      const h = new a.C(a.options);
      const buf = Buffer.from(message, 'latin1');
      feed(h, buf, 7, 130);
      assert.equal(toHex(h.finalize()), want);
    });
  }
  for (const [name, message, want, options] of published2) {
    it(`${name} ${JSON.stringify(options)} ${typeof message === 'string' ? 'empty' : toHex(String.fromCharCode(...message.subarray(0, 4))) + '...'}`, () => {
      assert.equal(hexOf(ALGOS[name].C, options, message), want);
    });
  }
});

describe('the S-boxes of Tiger are the published ones', () => {
  it('first and last words of the derived tables', () => {
    const t = tigerSbox();
    const word = (i) => (BigInt(t[2 * i + 1] >>> 0) << 32n) | BigInt(t[2 * i] >>> 0);
    assert.equal(word(0), 0x02AAB17CF7E90C5En);
    assert.equal(word(1), 0xAC424B03E243A8ECn);
    assert.equal(word(4), 0xCD9978FFD21F9193n);
    // Every byte column of every table is a permutation.
    for (let tab = 0; tab < 4; tab++) {
      for (let col = 0; col < 8; col++) {
        const seen = new Set();
        for (let i = 0; i < 256; i++) {
          const half = t[2 * (256 * tab + i) + (col >> 2)];
          seen.add((half >>> (8 * (col & 3))) & 255);
        }
        assert.equal(seen.size, 256);
      }
    }
  });
});

// ---- generated vectors (Tiger, Tiger2, Streebog) ------------------------------------------------------

perEngine('vectors from the Python implementations', () => {
  for (const name of ['tiger', 'tiger2', 'streebog256', 'streebog512']) {
    const a = ALGOS[name];
    const rows = vectors(a.file);
    it(`${name}: ${rows.length} lengths, one update and random pieces`, () => {
      for (const row of rows) {
        const message = pattern(row.length, row.tag);
        assert.equal(hexOf(a.C, a.options, message), row.digest, `length ${row.length}`);
        const h = new a.C(a.options);
        feed(h, message, row.length + 1);
        assert.equal(toHex(h.finalize()), row.digest, `length ${row.length}, pieces`);
      }
    });
  }
  const tiger = vectors('tiger.json');
  for (const [bits, C] of [[160, Tiger], [128, Tiger], [8, Tiger], [64, Tiger2]]) {
    it(`${C.name === 'Tiger' ? 'Tiger' : 'Tiger2'} with length ${bits} is the first ${bits / 8} bytes of the digest`, () => {
      const rows = C === Tiger ? tiger : vectors('tiger2.json');
      for (const row of rows.slice(0, 80)) {
        assert.equal(hexOf(C, { length: bits }, pattern(row.length, row.tag)), row.digest.slice(0, bits / 4));
      }
    });
  }
});

// ---- reference implementations built into Node -------------------------------------------------------

perEngine('CRC-32 against zlib', () => {
  it('matches zlib.crc32 for random messages of every length up to 400', () => {
    for (let n = 0; n <= 400; n++) {
      const message = bytes(n, n);
      const want = zlibCrc32(message).toString(16).padStart(8, '0');
      assert.equal(hexOf(Crc32, {}, message), want, `length ${n}`);
    }
  });
  it('matches zlib.crc32 for a long message in random pieces', () => {
    const message = bytes(300000, 9);
    const h = new Crc32();
    feed(h, message, 3, 5000);
    assert.equal(toHex(h.finalize()), zlibCrc32(message).toString(16).padStart(8, '0'));
  });
});

// ---- engines against each other ----------------------------------------------------------------------

describe('the wasm and the JavaScript engines agree', () => {
  const cases = [
    ['tiger', [{}, { length: 128 }]], ['tiger2', [{}, { length: 8 }]],
    ['streebog256', [{ length: 256 }]], ['streebog512', [{ length: 512 }]],
    ['crc32', [{}]], ['crc32c', [{}]],
    ['xxhash32', [{}, { seed: 1 }, { seed: 0xffffffff }, { seed: 0x9E3779B1 }]],
    ['xxhash64', [{}, { seed: 1 }, { seed: 0x1fffffffffffff }, { seed: 0x123456789ab }]],
  ];
  for (const [name, optionSets] of cases) {
    const a = ALGOS[name];
    it(`${name}: random lengths 0 to ${4 * a.block + 3}, then long messages`, () => {
      const lengths = [];
      for (let n = 0; n <= 4 * a.block + 3; n++) lengths.push(n);
      lengths.push(1000, 4096, 4097, 70000, 70001);
      for (const options of optionSets) {
        for (const n of lengths) {
          const message = bytes(n, n + 1);
          const viaWasm = hexOf(a.C, options, message);
          const viaJs = withJs(() => hexOf(a.C, options, message));
          assert.equal(viaJs, viaWasm, `${JSON.stringify(options)} length ${n}`);
        }
      }
      assert.ok(a.internal.wasmCalls() > 0, 'wasm ran');
    });
  }
});

// ---- behavior of the hasher interface ------------------------------------------------------------------

perEngine('the hasher interface', (label) => {
  for (const [name, a] of Object.entries(ALGOS)) {
    describe(name, () => {
      it('uses the engine under test', () => {
        const before = a.internal.wasmCalls();
        const h = new a.C(a.options);
        h.update(bytes(5 * a.block + 3, 1));
        h.finalize();
        assert.equal(a.internal.wasmCalls() > before, label === 'wasm');
      });

      it('finalize() is repeatable and update() continues the message', () => {
        const h = new a.C(a.options);
        const m = bytes(3 * a.block + 5, 2);
        h.update(m.subarray(0, a.block + 1));
        const first = toHex(h.finalize());
        assert.equal(toHex(h.finalize()), first);
        assert.equal(first, hexOf(a.C, a.options, m.subarray(0, a.block + 1)));
        h.update(m.subarray(a.block + 1));
        assert.equal(toHex(h.finalize()), hexOf(a.C, a.options, m));
      });

      it('reset() starts over, with the same options', () => {
        const h = new a.C(a.options);
        h.update('discard me');
        h.finalize();
        h.reset();
        h.update('abc');
        assert.equal(toHex(h.finalize()), hexOf(a.C, a.options, 'abc'));
      });

      it('getState() is JSON, and setState() resumes at any offset', () => {
        const m = bytes(4 * a.block + 7, 3);
        for (const cut of [0, 1, a.block - 1, a.block, a.block + 1, 2 * a.block, 3 * a.block + 2, m.length]) {
          const x = new a.C(a.options);
          x.update(m.subarray(0, cut));
          const state = JSON.parse(JSON.stringify(x.getState()));
          const y = new a.C(a.options);
          y.setState(state);
          y.update(m.subarray(cut));
          assert.equal(toHex(y.finalize()), hexOf(a.C, a.options, m), `cut ${cut}`);
        }
      });

      it('keeps the last block in state.message and the counts consistent', () => {
        const h = new a.C(a.options);
        h.update(bytes(5 * a.block, 4));
        const s = h.getState();
        assert.equal(s.length, 5 * a.block);
        assert.equal(s.message.length, a.block);
        assert.equal(s.counter, 4 * a.block);
        assert.ok(Array.isArray(s.hash) && s.hash.every(Number.isInteger));
      });

      it('accepts typed arrays and ArrayBuffers like binary strings, and refuses wide characters', () => {
        const m = bytes(100, 5);
        const want = hexOf(a.C, a.options, m);
        assert.equal(hexOf(a.C, a.options, m.toString('latin1')), want);
        assert.equal(hexOf(a.C, a.options, new Uint8Array(m)), want);
        assert.equal(hexOf(a.C, a.options, new Uint8Array(m).buffer), want);
        assert.throws(() => new a.C(a.options).update('Ā'), TypeError);
        assert.throws(() => new a.C(a.options).update(5), TypeError);
        assert.throws(() => new a.C(a.options).update(null), TypeError);
      });

      it('has the block size HMAC needs, and works with Hmac', () => {
        const h = new a.C(a.options);
        assert.ok(h instanceof Hasher);
        assert.equal(h.blockSizeInBytes, a.block);
        // HMAC from its definition, with this hasher.
        const key = Buffer.from('a key that is longer than the block of the smallest hashers here!');
        const message = Buffer.from('the message');
        const hash = (data) => Buffer.from(hexOf(a.C, a.options, data), 'hex');
        let k = key.length > a.block ? hash(key) : key;
        k = Buffer.concat([k, Buffer.alloc(a.block - k.length)]);
        const ipad = Buffer.from(k.map((b) => b ^ 0x36));
        const opad = Buffer.from(k.map((b) => b ^ 0x5c));
        const want = hash(Buffer.concat([opad, hash(Buffer.concat([ipad, message]))])).toString('hex');
        const mac = new Hmac(key, new a.C(a.options));
        mac.update(message);
        assert.equal(toHex(mac.finalize()), want);
      });

      it('refuses states that no engine can work on, the same way in both engines', () => {
        const state = () => new a.C(a.options).getState();
        const bad = [
          [(s) => { s.hash = 'x'; }, TypeError],
          [(s) => { s.hash.pop(); }, TypeError],
          [(s) => { s.hash[0] = 1.5; }, TypeError],
          [(s) => { s.counter = 'a'; }, TypeError],
          [(s) => { s.counter = 1; }, RangeError],
          [(s) => { s.counter = -a.block; }, RangeError],
          [(s) => { s.counter = a.block; s.message = ''; }, RangeError],
          [(s) => { s.message = 5; }, TypeError],
        ];
        for (const [mutate, Err] of bad) {
          const s = state();
          mutate(s);
          const h = new a.C(a.options);
          h.setState(s);
          assert.throws(() => h.finalize(), Err);
          const before = JSON.stringify(h.getState());
          assert.throws(() => h.finalize(), Err);
          assert.equal(JSON.stringify(h.getState()), before, 'a refused call leaves the state alone');
        }
      });
    });
  }
});

// ---- options ---------------------------------------------------------------------------------------------

describe('options', () => {
  const bad = [
    [Tiger, { length: 7 }, RangeError], [Tiger, { length: 200 }, RangeError], [Tiger, { length: 0 }, RangeError],
    [Tiger, { length: '192' }, TypeError], [Tiger2, { length: 192.5 }, RangeError],
    [Streebog, { length: 384 }, RangeError], [Streebog, { length: '256' }, TypeError], [Streebog, { length: 0 }, RangeError],
    [XxHash32, { seed: -1 }, RangeError], [XxHash32, { seed: 4294967296 }, RangeError], [XxHash32, { seed: 1.5 }, RangeError],
    [XxHash32, { seed: 'x' }, TypeError], [XxHash64, { seed: 2 ** 53 }, RangeError], [XxHash64, { seed: -1 }, RangeError],
    [XxHash64, { seed: NaN }, RangeError], [XxHash64, { seed: 1n }, TypeError],
    [Tiger, 5, TypeError], [Streebog, 'x', TypeError], [Crc32, true, TypeError], [XxHash32, 1, TypeError],
  ];
  for (const [C, options, Err] of bad) {
    it(`${C.name} ${typeof options === 'object' ? JSON.stringify(options, (k, v) => (typeof v === 'bigint' ? `${v}n` : v)) : String(options)} is refused with ${Err.name}`, () => {
      assert.throws(() => new C(options), Err);
    });
  }

  it('the defaults, and that the options object is not modified', () => {
    const options = {};
    new Tiger(options);
    new XxHash64(options);
    assert.deepEqual(options, {});
    assert.equal(new Tiger().options.length, 192);
    assert.equal(new Streebog().options.length, 512);
    assert.equal(new XxHash32().options.seed, 0);
    assert.equal(hexOf(Streebog, {}, 'abc'), hexOf(Streebog, { length: 512 }, 'abc'));
    assert.equal(hexOf(Streebog, { length: 256 }, 'abc').length, 64);
    assert.equal(hexOf(Tiger, { length: 160 }, 'abc').length, 40);
  });

  it('null and undefined options are the defaults', () => {
    for (const C of [Tiger, Tiger2, Streebog, Crc32, Crc32c, XxHash32, XxHash64]) {
      assert.equal(hexOf(C, undefined, 'abc'), hexOf(C, {}, 'abc'));
      assert.equal(hexOf(C, null, 'abc'), hexOf(C, {}, 'abc'));
    }
  });

  it('a seed changes the xxHash digest, and Tiger/Streebog ignore unknown options', () => {
    assert.notEqual(hexOf(XxHash32, { seed: 1 }, 'abc'), hexOf(XxHash32, {}, 'abc'));
    assert.notEqual(hexOf(XxHash64, { seed: 1 }, 'abc'), hexOf(XxHash64, {}, 'abc'));
    assert.equal(hexOf(Tiger, { nope: 1 }, 'abc'), hexOf(Tiger, {}, 'abc'));
  });
});

// ---- CryptoApi -----------------------------------------------------------------------------------------------

describe('CryptoApi', () => {
  it('getHasher() and hash() know the names', () => {
    const names = {
      tiger: Tiger, tiger192: Tiger, tiger160: Tiger, tiger128: Tiger, tiger2: Tiger2,
      streebog: Streebog, streebog256: Streebog, streebog512: Streebog,
      crc32: Crc32, crc32c: Crc32c, xxhash32: XxHash32, xxhash64: XxHash64,
    };
    for (const [name, C] of Object.entries(names)) {
      assert.ok(CryptoApi.getHasher(name) instanceof C, name);
    }
    assert.equal(CryptoApi.hash('tiger', 'abc'), '2aab1484e8c158f2bfb8c5ff41b57a525129131c957b5f93');
    assert.equal(CryptoApi.hash('tiger192', 'abc'), CryptoApi.hash('tiger', 'abc'));
    assert.equal(CryptoApi.hash('tiger160', 'abc'), '2aab1484e8c158f2bfb8c5ff41b57a525129131c');
    assert.equal(CryptoApi.hash('tiger128', 'abc'), '2aab1484e8c158f2bfb8c5ff41b57a52');
    assert.equal(CryptoApi.hash('tiger2', 'abc'), 'f68d7bc5af4b43a06e048d7829560d4a9415658bb0b1f3bf');
    assert.equal(CryptoApi.hash('streebog256', ''), '3f539a213e97c802cc229d474c6aa32a825a360b2a933a949fd925208d9ce1bb');
    assert.equal(CryptoApi.hash('streebog', ''), CryptoApi.hash('streebog512', ''));
    assert.equal(CryptoApi.hash('crc32', '123456789'), 'cbf43926');
    assert.equal(CryptoApi.hash('crc32c', '123456789'), 'e3069283');
    assert.equal(CryptoApi.hash('xxhash32', 'abc'), '32d153ff');
    assert.equal(CryptoApi.hash('xxhash64', 'abc'), '44bc2cf5ad770999');
    assert.equal(CryptoApi.hash('xxhash32', 'abc', { seed: 5 }), hexOf(XxHash32, { seed: 5 }, 'abc'));
  });

  it('hash() encodes text as UTF-8 and getHmac() works', () => {
    assert.equal(CryptoApi.hash('crc32', 'é'), toHex(hashOf(Crc32, fromUtf('é'))));
    assert.equal(CryptoApi.hmac('key', 'message', CryptoApi.getHasher('streebog256')).length, 64);
  });
});

function hashOf(C, message) {
  const h = new C();
  h.update(message);
  return h.finalize();
}
